<?php declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';$db=db();$token=(string)($_POST['token']??'');$id=(int)($_POST['id']??0);$decision=$_POST['decision']??'';$comment=trim((string)($_POST['comment']??''));if(!in_array($decision,['approved','rejected'],true)){http_response_code(400);exit('Invalid decision.');}$hash=hash('sha256',$token);$s=$db->prepare('SELECT s.*,c.id client_id FROM client_portal_sessions s JOIN clients c ON c.id=s.client_id WHERE s.token_hash=? AND s.expires_at>NOW()');$s->execute([$hash]);$session=$s->fetch();if(!$session){http_response_code(403);exit('Invalid or expired portal link.');}$q=$db->prepare('SELECT a.* FROM project_approvals a JOIN client_projects p ON p.id=a.project_id WHERE a.id=? AND p.client_id=?');$q->execute([$id,$session['client_id']]);$approval=$q->fetch();if(!$approval){http_response_code(404);exit('Approval request not found.');}$db->beginTransaction();$u=$db->prepare('UPDATE project_approvals SET status=?,client_comment=?,responded_at=NOW() WHERE id=? AND status="pending"');$u->execute([$decision,$comment,$id]);if($u->rowCount()){$db->prepare('INSERT INTO project_activity(project_id,actor_type,actor_id,activity_type,title,description,metadata) VALUES(?,"client",?,?,?, ?,?)')->execute([$approval['project_id'],$session['client_id'],'approval_'.$decision,'Client '.ucfirst($decision),$comment,json_encode(['approval_id'=>$id],JSON_THROW_ON_ERROR)]);} $db->commit();header('Location: project.php?token='.urlencode($token).'&id='.(int)$approval['project_id']);exit;